$('flightUfoModel').onchange=()=>selectUfoModel($('flightUfoModel').value);syncUfoModelOptions();
function threatPriority(target){return ['fighter','blackhawk','sr71'].includes(target.type)?0:1;}
function hostileTargets(){return [...aircraft,...targets.filter(t=>t.enemy&&!t.lift),...lights].filter(t=>t.health>0);}
function currentWeapons(){return weaponProfile({tier:missionType==='abduct'&&ufoModel==='tr3b'&&tr3bUnlocked?tr3bLevel:0,altitude:GROUND-player.y,weaponLevel:player.weapon||1});}
function ufoMissileTarget(){const choices=hostileTargets().filter(t=>combatDistance(t,player)<currentWeapons().lockRange).sort((a,b)=>threatPriority(a)-threatPriority(b)||combatDistance(a,player)-combatDistance(b,player));return choices.find(t=>t.id===lockedTargetId)||choices[0];}
function cycleWeaponLock(){if(state!=='playing'||missionType!=='abduct')return;const choices=hostileTargets().filter(t=>combatDistance(t,player)<currentWeapons().lockRange).sort((a,b)=>a.id-b.id);if(!choices.length)return;const current=ufoMissileTarget(),index=choices.findIndex(t=>t.id===current?.id);const chosen=choices[(index+1)%choices.length];lockedTargetId=chosen.id;dispatch('LOCK: '+(chosen.type?chosen.type.toUpperCase():'SAM BATTERY')+' • F LASER / R MISSILE / T NEXT',2);}
function weaponImpact(m,target){
 const point={x:target?.x??m.x,y:target?.y??m.y,z:target?.z??m.z},radius=m.blastRadius||0;
 burst(point.x,point.y,32,'#ffbd77',200,point.z);
 if(m.orbital||radius>0)orbitalImpacts.push({id:newId(),...point,radius:Math.max(35,radius),life:5,maxLife:5,label:m.orbital?'ORBITAL IMPACT • STRIKE CONFIRMED':'MISSILE IMPACT'});
 if(target){damageTarget(target,m.damage);if(target.health<=0)destroyHostile(target,true);}
 if(radius>0)for(const other of hostileTargets())if(other!==target){const amount=splashDamage(combatDistance(point,other),radius,m.damage);if(amount>0){damageTarget(other,amount);if(other.health<=0)destroyHostile(other,true);}}
 checkObjectives();
}
function launchUfoMissile(){
 if(state!=='playing'||missionType!=='abduct'||missileCooldown>0)return false;
 if(missileAmmo<=0){dispatch('MISSILE FABRICATOR RECHARGING',1.5);return false;}
 const target=ufoMissileTarget();if(!target){dispatch('NO MISSILE LOCK • CLOSE WITH A HOSTILE CONTACT',1.5);return false;}
 missileAmmo--;missileCooldown=1.2;if(missileReload<=0)missileReload=ufoSystems().missileReload;
 const payload=currentWeapons();const launched=fireMissile(player,target,false,payload.missileDamage,payload.missileSpeed);Object.assign(launched,{life:payload.missileLifetime,blastRadius:payload.missileBlastRadius,orbital:payload.orbital});dispatch('MISSILE AWAY • '+(target.type==='soldier'?'GROUND HOSTILE':target.type?target.type.toUpperCase():'SAM BATTERY'),1.3);return true;
}
function damageTarget(target,amount){
 if(target.health<=0)return;target.health=Math.max(0,target.health-amount);target.hitFlash=.14;target.healthShown=3.2;
 if(!(target.impactCooldown>0)){target.impactCooldown=.11;burst(target.x,target.y,7,'#e7ffe9',110,target.z);burst(target.x,target.y,4,'#b88aff',60,target.z);}
}
function updateDamageFeedback(dt){for(const target of [...aircraft,...aliens,...lights,...targets.filter(t=>t.enemy)]){target.hitFlash=Math.max(0,(target.hitFlash||0)-dt);target.healthShown=Math.max(0,(target.healthShown||0)-dt);target.impactCooldown=Math.max(0,(target.impactCooldown||0)-dt);}}
function beginAircraftCrash(target,type=target.type||'ufo'){
 if(target.crashStarted)return null;target.crashStarted=true;
 const heading=Number.isFinite(target.heading)?target.heading:Math.atan2(target.x-(target.goalX??target.x),target.z-(target.goalZ??target.z));
 const speed=type==='sr71'?310:type==='fighter'?210:type==='blackhawk'?95:130;
 const wreck={id:newId(),type,x:target.x,y:target.y,z:target.z??900,vx:Number.isFinite(target.vx)?target.vx:-Math.sin(heading)*speed,vy:12,vz:Number.isFinite(target.vz)?target.vz:-Math.cos(heading)*speed,heading,pitch:target.pitch||0,roll:target.roll||0,age:0,impacted:false,impactAge:0,seed:target.id||entityId,spin:(target.id%2?1:-1)*.6};
 wrecks.push(wreck);return wreck;
}
function updateWrecks(dt){
 for(const wreck of wrecks){
  wreck.age+=dt;
  if(wreck.impacted){wreck.impactAge+=dt;continue;}
  wreck.vy+=78*dt;wreck.vx*=Math.exp(-dt*.23);wreck.vz*=Math.exp(-dt*.23);
  wreck.x=clamp(wreck.x+wreck.vx*dt,15,WORLD-15);wreck.z=clamp(wreck.z+wreck.vz*dt,15,1785);wreck.y+=wreck.vy*dt;
  wreck.pitch=lerp(wreck.pitch,-.85,1-Math.exp(-dt*.55));wreck.roll+=wreck.spin*dt;wreck.heading+=wreck.spin*dt*.12;
  const groundY=surfaceY(wreck.x,wreck.z)-7;
  if(wreck.y>=groundY){
   wreck.y=groundY;wreck.impacted=true;wreck.impactAge=0;wreck.vx=wreck.vy=wreck.vz=0;wreck.pitch=-.12;wreck.roll=clamp(wreck.roll,-.7,.7);
   burst(wreck.x,wreck.y-8,72,'#ffb058',240,wreck.z);burst(wreck.x,wreck.y-8,35,'#fff1b0',140,wreck.z);tone(48,.65,'sawtooth',.28,0,20);
  }
 }
 wrecks=wrecks.filter(w=>!w.impacted||w.impactAge<8);
}
