 for(let i=1;i<=32;i++){const t=i/32;safeHeight=Math.max(safeHeight,terrainHeight(level,lerp(player.x,end.x,t),lerp(player.z,end.z,t))+210);}
 autopilotCruiseY=clamp(GROUND-safeHeight,-110,surfaceY(player.x,player.z)-160);autopilot=true;clearInput();player.dash=0;
