 if(target.enemy&&targets.includes(target)){if(target.type==='policeCar')beginAircraftCrash(target,'policeCar');stopTroop(target);}
 else if(target.type){beginAircraftCrash(target);aircraft=aircraft.filter(a=>a!==target);score+=400;credits+=20;dispatch('AIRCRAFT DISABLED • BURNING CONTACT GOING DOWN',2);}
 else{target.health=0;missionStats.sam++;score+=800;credits+=50;dispatch('SAM BATTERY DISABLED',2);}
