 const labels={intel:CAMPAIGN_STORY[level-1].intelLabel,cow:'Abduct cattle',human:'Abduct humans',ground:'Collect ground specimens',blackhawk:'Capture Black Hawks intact',fighter:'Capture fighters intact',sam:'Disable SAM batteries',sr71:'Capture the SR-71 Blackbird intact',alien:'Rescue the stranded alien crew'};const m=missions[level-1];return Object.keys(labels).filter(k=>m[k]).map(k=>({label:labels[k],detail:CAMPAIGN_STORY[level-1].objectiveDetails[k]||'REQUIRED: '+m[k]})).concat(level===6?[{label:'Evade or fight the recovery troops',detail:'Evade rifle fire or hold F to disable troops. Your laser protects friendly crew.'}]:[]).concat({label:'Reach the extraction beacon',detail:'After all required goals, press GO in the mission tracker for autopilot, or fly to the blue radar beacon.'});
