function dash(){if(state!=='playing'||(missionType==='abduct'?player.boostCharges<=0:player.dashCooldown>0)||player.dash>0)return;cancelExtractionAutopilot();let x=(keys.has('d')||keys.has('arrowright')?1:0)-(keys.has('a')||keys.has('arrowleft')?1:0)+joy.x,z=(keys.has('s')||keys.has('arrowdown')?1:0)-(keys.has('w')||keys.has('arrowup')?1:0)+joy.y;if(Math.hypot(x,z)<.1){x=Math.sin(player.heading);z=-Math.cos(player.heading);}const mag=Math.hypot(x,z);player.dashX=world.cameraMode==='chase'?-Math.sin(player.heading):x/mag;player.dashZ=world.cameraMode==='chase'?-Math.cos(player.heading):z/mag;player.dash=missionType==='abduct'?ufoSystems().boostDuration:.32;player.invincible=missionType==='abduct'?.8:.55;if(missionType==='abduct'){player.boostCharges--;if(player.boostRecharge<=0)player.boostRecharge=ufoSystems().boostRecharge;}player.dashCooldown=missionType==='abduct'?0:3.5-upgrades.engine*.45;missiles.filter(m=>m.hostile).forEach(m=>m.homing=false);threat=Math.max(0,threat-30);burst(player.x,player.y,18,'#ffbb75',130,player.z);sound('dash');}
