function effects(dt){particles=particles.filter(p=>{p.life-=dt;p.x+=p.vx*dt;p.y+=p.vy*dt;p.z+=(p.vz||0)*dt;return p.life>0;});popups=popups.filter(p=>{p.life-=dt;p.y-=dt*28;return p.life>0;});ghosts=ghosts.filter(p=>{p.life-=dt;return p.life>0;});shake=Math.max(0,shake-dt*35);if(dispatchTimer>0){dispatchTimer-=dt;if(dispatchTimer<=0)$('dispatch').hidden=true;}}
function drawCodeRain(){if(clock-rainStamp<.085)return;rainStamp=clock;const r=shell.getBoundingClientRect(),w=Math.round(r.width),h=Math.round(r.height);if(rainCanvas.width!==w||rainCanvas.height!==h){rainCanvas.width=w;rainCanvas.height=h;}rainCtx.clearRect(0,0,w,h);const menu=state!=='playing',columns=Math.floor(w/29);rainCtx.font='13px Courier New';rainCtx.textAlign='center';for(let c=0;c<columns;c++){if(!menu&&c>1&&c<columns-2)continue;const speed=reduced?0:clock*22;const head=((speed+c*83)%(h+280))-60;for(let row=0;row<12;row++){const y=head-row*18;if(y<0||y>h)continue;const v=Math.sin(c*119+row*37+Math.floor((reduced?0:clock)*.6))*10000;const char='01ABCDEF<>'.charAt(Math.abs(Math.floor(v))%10);rainCtx.fillStyle=c%7===0?'#ad79ff':'#00ff66';rainCtx.globalAlpha=(menu?.26:.075)*(1-row/13);rainCtx.fillText(char,17+c*29,y);}}rainCtx.globalAlpha=1;}
function render(dt){drawCodeRain();const menu=state==='menu'||state==='tutorial'||state==='briefing'||state==='help'&&(previousState==='menu'||previousState==='briefing');const sceneLevel=state==='briefing'||state==='help'&&previousState==='briefing'?level:menu?selectedStage:level;world.draw({level:sceneLevel,player,playerType:playerType(),menu,time:clock,dt,wreckDt:state==='playing'||state==='bay'||state==='end'?dt:0,targets,intelSites,orbitalImpacts,lights:lights.filter(l=>l.health>0),aircraft,missiles,aliens,wrecks,particles,laser,reduced,ufoLevel:tr3bLevel,orbitCapable:missionType==='abduct'&&ufoModel==='tr3b'&&tr3bUnlocked,hull:player.hull??100,extraction,beamAnchor:activeIntel||targets.find(t=>t.lift)||aircraft.find(a=>a.capture>0)});$('radar').hidden=state!=='playing';$('radarLegend').hidden=state!=='playing';$('objective').hidden=state!=='playing';$('telemetry').hidden=state!=='playing';$('flightReticle').hidden=state!=='playing';$('headingReadout').textContent='HDG '+String(Math.round(((player.heading||0)*-180/Math.PI+360)%360)).padStart(3,'0');drawMarkers();}
function drawMarkers(){const layer=$('markers');layer.replaceChildren();if(state!=='playing')return;const orbital=GROUND-player.y>=1500;const near=targets.filter(t=>!t.lift&&(orbital||flatDistance(t,player)<(t.type==='alien'?1800:800))).sort((a,b)=>Number(isMissionTarget(b))-Number(isMissionTarget(a))||flatDistance(a,player)-flatDistance(b,player)).slice(0,orbital?50:12);const list=[...intelSites.filter(t=>!t.complete).map(t=>({...t,label:CAMPAIGN_STORY[level-1].intelLabel+' · '+Math.round(flatDistance(t,player))+'m'+(t.scan>0?' · '+Math.round(t.scan/2.5*100)+'%':'' )})),...orbitalImpacts.map(t=>({...t,label:t.label||'IMPACT CONFIRMED'})),...targets.filter(t=>t.lift).map(t=>({...t,label:t.type==='alien'?'RESCUING CREW':'TRACTOR LOCK'})),...aircraft.filter(a=>a.capture>0).map(a=>({...a,label:'RESISTING '+Math.round(a.capture/(a.type==='sr71'?4:a.type==='fighter'?1.9:1.5)*100)+'%'})),...aliens.map(a=>({...a,label:'UFO • '+Math.ceil(a.health/120*100)+'%'})),...near.map(t=>({...t,bracket:true,label:(t.type==='alien'?'RESCUE '+(t.crewName||'CREW'):t.type==='policeCar'?'POLICE CAR':t.type==='policeOfficer'?'POLICE':t.enemy?'HOSTILE TROOPS':t.type==='human'?'HUMAN':t.type==='civilianCar'?'CIVILIAN CAR':t.type==='gold'?'GOLDEN CATTLE':'CATTLE')+(isMissionTarget(t)?' • GOAL':'')+' · '+Math.round(flatDistance(t,player))+'m'})),...lights.filter(l=>l.health>0&&(orbital||flatDistance(l,player)<1000)).map(l=>({...l,type:'sam',enemy:true,bracket:true,label:'SAM'+(isMissionTarget({type:'sam'})?' • GOAL':'')+' · '+Math.round(flatDistance(l,player))+'m'}))];if(level===6&&missionType==='abduct'&&!extraction){const c=getStage(6).crashSite;list.push({...c,y:surfaceY(c.x,c.z)-45,label:'CRASH SITE • '+(missionStats.alien||0)+'/6 RESCUED'});}if(extraction){const e=getStage(level).extract;list.push({x:e.x,y:surfaceY(e.x,e.z)-40,z:e.z,label:'EXTRACTION'});}if(missionType==='abduct'){const lock=ufoMissileTarget();if(lock)list.push({...lock,weaponLock:true,label:(currentWeapons().orbital?'ORBITAL ':'')+(lock.type?lock.type.toUpperCase():'SAM')+' LOCK • '+(touchEnabled?'TAP: NEXT TARGET':'F LASER / R MSL / T NEXT'),y:lock.y-18});}for(const a of [...aircraft,...aliens])if(a.healthShown>0&&a.health>0)list.push({...a,healthMarker:true,label:a.type==='blackhawk'?'BLACK HAWK':a.type==='sr71'?'SR-71':a.type==='fighter'?'FIGHTER':'UFO'});const placed=[],callouts=[];for(const t of list){const p=world.project({...t,y:t.y-(t.bracket?9:0)});if(!p.visible)continue;if(t.bracket&&p.x>world.width-235&&p.y>world.height-260)continue;if(t.bracket&&placed.some(q=>Math.abs(q.x-p.x)<(orbital?9:125)&&Math.abs(q.y-p.y)<(orbital?9:45)))continue;placed.push(p);const d=document.createElement(t.weaponLock?'button':'span');if(t.weaponLock){d.type='button';d.onclick=cycleWeaponLock;d.setAttribute('aria-label','Cycle weapon lock to the next hostile target');d.style.pointerEvents='auto';}else d.setAttribute('aria-hidden','true');d.className=t.healthMarker?'aircraft-health'+(t.hitFlash>0?' is-hit':'')+(t.health/(t.maxHealth||120)<.35?' is-critical':''):t.bracket?'target-bracket':'target-marker';d.style.left=(t.healthMarker?clamp(p.x,80,world.width-80):p.x)+'px';let markerY=t.healthMarker?Math.max(40,p.y-65):p.y-(t.bracket?0:45);if(orbital&&!t.healthMarker&&!t.bracket){for(let tries=0;tries<8&&callouts.some(q=>Math.abs(q.x-p.x)<310&&Math.abs(q.y-markerY)<34);tries++)markerY-=36;markerY=Math.max(75,markerY);callouts.push({x:p.x,y:markerY});d.classList.add('orbital-callout');}d.style.top=markerY+'px';if(t.healthMarker){const percent=Math.max(0,Math.ceil(t.health/(t.maxHealth||120)*100)),track=goalElement('span','aircraft-health-track'),fill=goalElement('i','');fill.style.width=percent+'%';track.append(fill);d.append(goalElement('span','aircraft-health-name',t.label),goalElement('strong','aircraft-health-value',percent+'%'),track);}else if(t.bracket){d.dataset.label=t.label;if(orbital)d.classList.add('orbital-target');if(t.enemy)d.classList.add('hostile','target-hostile');else if(t.type==='human')d.classList.add('target-human');else if(t.type==='cow'||t.type==='gold')d.classList.add('target-cattle');else if(t.type==='civilianCar')d.classList.add('target-vehicle');if(t.type==='alien')d.classList.add('rescue','target-alien');if(isMissionTarget(t))d.classList.add('mission-target');}else d.textContent=t.label;layer.append(d);}}
function frame(now){const dt=Math.min((now-last)/1000||0,.04);last=now;clock+=dt;if(state==='ending'){updateRescueEnding(dt);requestAnimationFrame(frame);return;}if(state==='playing'){update(dt);effects(dt);}if(state==='playing'||state==='bay'||state==='end')updateWrecks(dt);if(policeSirenGain&&audioCtx){const nearby=state==='playing'?targets.filter(t=>t.siren&&flatDistance(t,player)<650).sort((a,b)=>flatDistance(a,player)-flatDistance(b,player))[0]:null;policeSirenGain.gain.setTargetAtTime(!muted&&nearby?.1*(1-flatDistance(nearby,player)/650):0,audioCtx.currentTime,.18);policeSirenOsc.frequency.setTargetAtTime(760+Math.sin(clock*7)*220,audioCtx.currentTime,.05);}if(humGain&&audioCtx)humGain.gain.setTargetAtTime(!muted&&state==='playing'?(player.beam?.06:.018):0,audioCtx.currentTime,.12);updateGoalFeedback(dt);render(dt);requestAnimationFrame(frame);}
